SET statement_timeout = '60s';
SELECT * FROM ag_catalog.cypher('yago2geo_uk_subset', $$
MATCH (cambridge)
WHERE (cambridge.uri = 'http://yago-knowledge.org/resource/Cambridge' OR cambridge.yago_uri = 'http://yago-knowledge.org/resource/Cambridge')
RETURN ST_Area(cambridge.geom) AS totalArea
$$) AS (totalArea agtype);

